from pyspark import pipelines as dp
from pyspark.sql.functions import col

@dp.table
def silver_transactions():
    dp.expect('valid_amount', col('amount') > 0)
    dp.expect_or_drop('valid_customer', col('customer_id').isNotNull())
    return dp.read('bronze_transactions').filter(col('status') == 'completed')

